function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}function line(x,y,x2,y2,c,w=1){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke()}
function drawWorld(){ctx.fillStyle='#11101a';ctx.fillRect(0,0,W,H);
// distant neon skyline
for(let i=0;i<18;i++){let x=i*58-15,h=90+(i*37%100);rect(x,72-h,49,h,'#171522');rect(x+5,77-h,39,h-6,'#1b1828');for(let wy=0;wy<Math.floor(h/15);wy++)for(let wx=0;wx<3;wx++)if((i*5+wy*3+wx)%4!==0)rect(x+10+wx*11,83-h+wy*15,4,6,(i+wy)%2?'#ff3b8d35':'#5af5ed2b')}
// road and sidewalk
rect(0,86,W,16,'#29202c');rect(0,102,W,H-102,'#17151e');rect(0,105,W,2,'#63314d');rect(0,125,W,H-125,'#191821');for(let x=0;x<W;x+=48){rect(x,107,24,2,'#40303d');rect(x+12,88,2,12,'#50404a')}
// road markings
for(let y=190;y<H;y+=86){rect(0,y,W,1,'#282530');for(let x=30;x<W;x+=110)rect(x,y+21,37,2,'#3b3440')}
// puddles / texture accents
for(let i=0;i<9;i++){let x=(i*127+43)%W,y=165+(i*83%420);ctx.fillStyle='#5af5ed';ctx.globalAlpha=.07;ctx.fillRect(x,y,50+(i%3)*16,3);ctx.globalAlpha=1}
// vending machines and neon signs
for(let i=0;i<4;i++){let x=35+i*260;rect(x,137,35,72,'#211d2b');rect(x+4,141,27,42,i%2?'#ff3b8d':'#5af5ed');rect(x+7,145,21,34,'#171524');rect(x+8,190,19,3,'#534253');rect(x+12,198,12,4,'#312c38');ctx.font='9px monospace';ctx.fillStyle=i%2?colors.pink:colors.cyan;ctx.fillText(i%2?'24H':'OPEN',x+3,132)}
