for(let x=128;x<W;x+=256){rect(x,120,1,H-120,'#27232d');rect(x+1,120,1,H-120,'#ff3b8d15')}
}
function drawPlayer(){let p=player;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);if(p.invuln>0&&Math.floor(time*18)%2===0)ctx.globalAlpha=.45;
// shadow + legs
rect(-9,6,19,7,'#090910');rect(-7,1,6,9,'#292532');rect(2,1,6,9,'#292532');
// jacket silhouette
rect(-10,-8,20,17,'#171523');rect(-8,-9,16,16,'#c22666');rect(-7,-8,7,13,'#e6427f');rect(1,-8,6,13,'#842553');rect(-9,5,18,3,'#5af5ed');
// head, hair, visor
rect(-5,-16,11,9,'#e8aa9b');rect(-7,-18,14,5,'#25202e');rect(-4,-13,10,3,'#5af5ed');rect(3,-12,4,2,'#fff');
// arm / blade
rect(7,-4,10,4,'#d7a396');rect(12,-5,18,2,'#a7fff5');rect(29,-6,3,4,'#fff');ctx.restore();
